= BerryTreeScript
special ObjectEventInteractionGetBerryTreeData
switch VAR_0x8004
case BERRY_STAGE_SPARKLING BerryTree_EventScript_Sparkling
case BERRY_STAGE_NO_BERRY BerryTree_EventScript_CheckSoil
case BERRY_STAGE_PLANTED BerryTree_EventScript_CheckBerryStage1
case BERRY_STAGE_SPROUTED BerryTree_EventScript_CheckBerryStage2
case BERRY_STAGE_TALLER BerryTree_EventScript_CheckBerryStage3
case BERRY_STAGE_FLOWERING BerryTree_EventScript_CheckBerryStage4
case BERRY_STAGE_BERRIES BerryTree_EventScript_CheckBerryFullyGrown
end
= BerryTree_EventScript_CheckBerryFullyGrown
buffernumberstring STR_VAR_2 VAR_0x8006
lock
faceplayer
special ObjectEventInteractionGetBerryCountString
msgbox	BerryTree_Text_WantToPick
goto_if_eq VAR_RESULT YES BerryTree_EventScript_PickBerry
goto_if_eq VAR_RESULT NO BerryTree_EventScript_CancelPickingBerry
goto BerryTree_EventScript_PickBerry
= BerryTree_EventScript_PickBerry
special ObjectEventInteractionPickBerryTree
goto_if_eq VAR_0x8004 0 BerryTree_EventScript_BerryPocketFull
special IncrementDailyPickedBerries
special ObjectEventInteractionRemoveBerryTree
msgbox	BerryTree_Text_PickedTheBerry
playfanfare MUS_OBTAIN_BERRY
waitmessage
waitfanfare
waitbuttonpress
msgbox	BerryTree_Text_PutAwayBerry
waitmessage
waitbuttonpress
release
end
= BerryTree_EventScript_BerryPocketFull
msgbox	BerryTree_Text_BerryPocketFull
waitmessage
waitbuttonpress
release
end
= BerryTree_EventScript_CancelPickingBerry
msgbox	BerryTree_Text_BerryLeftUnpicked
waitmessage
waitbuttonpress
release
end
= BerryTree_EventScript_CheckBerryStage4
call BerryTree_EventScript_GetCareAdverb
lockall
special ObjectEventInteractionGetBerryName
msgbox	BerryTree_Text_BerryGrowthStage4
waitmessage
waitbuttonpress
goto BerryTree_EventScript_WantToWater
@ VAR_0x8005 here is the number of times watered
@ Buffered by ObjectEventInteractionGetBerryTreeData
goto BerryTree_EventScript_GetCareAdverb
= BerryTree_EventScript_GetCareAdverb
goto_if_eq VAR_0x8005 0 BerryTree_EventScript_SetAdverbPoor
goto_if_eq VAR_0x8005 4 BerryTree_EventScript_SetAdverbGreat
bufferstring STR_VAR_2 BerryTree_Text_CareAdverbGood
return
= BerryTree_EventScript_SetAdverbGreat
bufferstring STR_VAR_2 BerryTree_Text_CareAdverbGreat
return
= BerryTree_EventScript_SetAdverbPoor
bufferstring STR_VAR_2 BerryTree_Text_CareAdverbPoor
return
@ VAR_0x8006 here is the number of berries
goto BerryTree_EventScript_CheckBerryFullyGrown
= BerryTree_EventScript_WantToWater
checkitem ITEM_WAILMER_PAIL
goto_if_eq VAR_RESULT FALSE BerryTree_EventScript_DontWater
special ObjectEventInteractionGetBerryName
msgbox	BerryTree_Text_WantToWater
goto_if_eq VAR_RESULT YES BerryTree_EventScript_WaterBerry
goto_if_eq VAR_RESULT NO BerryTree_EventScript_DontWater
goto BerryTree_EventScript_DontWater
= BerryTree_EventScript_DontWater
releaseall
end
= BerryTree_EventScript_WaterBerry
special ObjectEventInteractionGetBerryName
msgbox	BerryTree_Text_WateredTheBerry
waitmessage
special ObjectEventInteractionWaterBerryTree
special DoWateringBerryTreeAnim
msgbox	BerryTree_Text_PlantIsDelighted
waitmessage
waitbuttonpress
releaseall
end
= BerryTree_EventScript_CheckBerryStage3
lockall
special ObjectEventInteractionGetBerryName
msgbox	BerryTree_Text_BerryGrowthStage3
waitmessage
waitbuttonpress
goto BerryTree_EventScript_WantToWater
= BerryTree_EventScript_CheckBerryStage2
lockall
special ObjectEventInteractionGetBerryName
msgbox	BerryTree_Text_BerryGrowthStage2
waitmessage
waitbuttonpress
goto BerryTree_EventScript_WantToWater
= BerryTree_EventScript_CheckBerryStage1
lockall
special ObjectEventInteractionGetBerryCountString
msgbox	BerryTree_Text_BerryGrowthStage1
waitmessage
waitbuttonpress
goto BerryTree_EventScript_WantToWater
= BerryTree_EventScript_CheckSoil
lock
faceplayer
specialvar VAR_RESULT PlayerHasBerries
goto_if_eq VAR_RESULT TRUE BerryTree_EventScript_WantToPlant
msgbox	BerryTree_Text_ItsSoftLoamySoil
waitmessage
waitbuttonpress
release
end
= BerryTree_EventScript_WantToPlant
msgbox	BerryTree_Text_WantToPlant
goto_if_eq VAR_RESULT YES BerryTree_EventScript_ChooseBerryToPlant
goto_if_eq VAR_RESULT NO BerryTree_EventScript_CancelPlanting
end
= BerryTree_EventScript_CancelPlanting
release
end
= BerryTree_EventScript_ChooseBerryToPlant
fadescreen FADE_TO_BLACK
closemessage
special Bag_ChooseBerry
goto_if_eq VAR_ITEM_ID 0 BerryTree_EventScript_CancelPlanting
removeitem VAR_ITEM_ID
call BerryTree_EventScript_PlantBerry
goto BerryTree_EventScript_CancelPlanting
= BerryTree_EventScript_PlantBerry
special ObjectEventInteractionPlantBerryTree
incrementgamestat GAME_STAT_PLANTED_BERRIES
special IncrementDailyPlantedBerries
special ObjectEventInteractionGetBerryCountString
msgbox	BerryTree_Text_PlantedOneBerry
waitmessage
waitbuttonpress
return
= BerryTree_EventScript_Sparkling
lockall
msgbox	BerryTree_Text_ExclamationPoint
waitmessage
waitbuttonpress
releaseall
end
= Route112_EventScript_MagmaGrunts
lockall
delay 40
applymovement LOCALID_ROUTE112_GRUNT_1 Common_Movement_WalkInPlaceFasterRight
waitmovement 0
delay 20
msgbox	Hey, man, is our leader really going to awaken that thing?
closemessage
applymovement LOCALID_ROUTE112_GRUNT_1 Common_Movement_FaceOriginalDirection
waitmovement 0
delay 40
applymovement LOCALID_ROUTE112_GRUNT_2 Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
delay 20
msgbox	Sounds like it, yeah. But I heard we need a METEORITE to do it.
closemessage
applymovement LOCALID_ROUTE112_GRUNT_2 Common_Movement_FaceOriginalDirection
waitmovement 0
delay 40
applymovement LOCALID_ROUTE112_GRUNT_1 Common_Movement_WalkInPlaceFasterRight
waitmovement 0
delay 20
msgbox	Oh, I get it now. That's why the rest of the crew went out to FALLARBOR.
closemessage
applymovement LOCALID_ROUTE112_GRUNT_1 Common_Movement_FaceOriginalDirection
waitmovement 0
delay 40
applymovement LOCALID_ROUTE112_GRUNT_2 Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
delay 20
msgbox	You got it. And until they come back, we're not to let anyone pass, right.
closemessage
applymovement LOCALID_ROUTE112_GRUNT_2 Common_Movement_FaceOriginalDirection
waitmovement 0
releaseall
end
= Route112_EventScript_Trent
trainerbattle_single TRAINER_TRENT_1 Route112_Text_TrentIntro Route112_Text_TrentDefeat Route112_EventScript_RegisterTrent
specialvar VAR_RESULT ShouldTryRematchBattle
goto_if_eq VAR_RESULT TRUE Route112_EventScript_RematchTrent
msgbox	Try hiking, and I mean really pounding, on these mountain trails with a heavy pack weighing dozens of pounds.That, my friend, will get your body into serious shape.
release
end
= Route112_EventScript_RematchTrent
trainerbattle_rematch TRAINER_TRENT_1 Route112_Text_TrentRematchIntro Route112_Text_TrentRematchDefeat
msgbox	I hear there are some seriously tough TRAINERS on top of MT. CHIMNEY.I intend to get up there and give them a challenge!
end
= Route112_EventScript_RegisterTrent
special PlayerFaceTrainerAfterBattle
waitmovement 0
msgbox	Ow, my legs have cramped up. Can you grab me some bandages from my backpack?No, that's my POKéNAV! Oh, fine, I'll register you.
register_matchcall TRAINER_TRENT_1
release
end
= Route112_EventScript_Carol
trainerbattle_single TRAINER_CAROL Route112_Text_CarolIntro Route112_Text_CarolDefeat
msgbox	It doesn't matter if you're good or bad at singing or POKéMON.If you have the most fun, you win!
end
= Route112_EventScript_Larry
trainerbattle_single TRAINER_LARRY Route112_Text_LarryIntro Route112_Text_LarryDefeat
msgbox	I'm not crying because I miss my mommy! Snivel…
end
= Route112_EventScript_Brice
trainerbattle_single TRAINER_BRICE Route112_Text_BriceIntro Route112_Text_BriceDefeat
msgbox	Hahahahaha! Something flew up my nose! Hahahaha-hatchoo!
end
